<!-- @generated by qw-codegen (tree) -->
<template>
  <view class="qw-detail qw-stack">
    <QwPerm :perm="topicPerms.create">
      <wd-button custom-class="qw-btn qw-btn--primary" type="primary" block @click="create">
        {{ t('crud.action.create') }}
      </wd-button>
    </QwPerm>
    <view
      v-for="row in rows"
      :key="row.id"
      class="qw-card qw-row"
      :role="canView ? 'link' : undefined"
      @click="open(row.id)"
    >
      <view class="qw-row__main">
        <view class="qw-row__line">
          <text class="qw-row__title">{{ row.title }}</text>
          <text :class="`qw-tag qw-tag--${dictTag('core.enabled', row.enabled).type}`">{{
            dictTag('core.enabled', row.enabled).label
          }}</text>
          <text class="qw-row__time">{{ formatShort(row.createdAt) }}</text>
        </view>
      </view>
      <!-- a node with children: their level, one tap -->
      <text v-if="row.children.length" class="qw-sec__link" @click.stop="drill(row.id)">{{
        t('crud.tree.children', { n: row.children.length })
      }}</text>
    </view>
    <QwEmpty v-if="loaded && !rows.length" :title="error || t('crud.empty')" />
  </view>
</template>

<script setup lang="ts">
import { computed, ref, shallowRef } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { topicPerms, type TopicVo } from '@qiwu/shared'
import { topicApi } from '@/api/demo/topic'
import QwEmpty from '@/core/components/QwEmpty.vue'
import QwPerm from '@/core/components/QwPerm.vue'
import { findNode, type TreeRow, useDicts } from '@/core/crud'
import { formatShort } from '@/core/format'
import { t } from '@/core/i18n'
import { errorText } from '@/core/request'
import { hasPerm } from '@/core/stores/auth'

/**
 * The topics (mobile, generated): one level of the tree, `?parentId=` (default: the
 * top level). The API answers the whole forest (no paging); a row opens its detail, its children link the
 * next level down. Showing again (back from a form or detail) reloads.
 */
const parentId = ref(0)
const forest = shallowRef<TreeRow<TopicVo>[]>([])
const loaded = ref(false)
const error = ref('')
const parent = computed(() => (parentId.value ? findNode(forest.value, parentId.value) : undefined))
const rows = computed(() => (parentId.value ? (parent.value?.children ?? []) : forest.value))
const { dictTag } = useDicts(['core.enabled'])

const canView = computed(() => hasPerm(topicPerms.view))
const open = (id: number) =>
  canView.value && uni.navigateTo({ url: `/pages-biz/demo/topic/detail?id=${id}` })
const create = () =>
  uni.navigateTo({ url: `/pages-biz/demo/topic/form?parentId=${parentId.value}` })
const drill = (id: number) => uni.navigateTo({ url: `/pages-biz/demo/topic/index?parentId=${id}` })

async function load() {
  try {
    forest.value = await topicApi.list()
    error.value = ''
  } catch (e) {
    error.value = errorText(e)
  } finally {
    loaded.value = true
  }
  const label = parent.value?.title
  uni.setNavigationBarTitle({ title: label || t('menu.demo.topic') })
}

onLoad((query) => (parentId.value = Number(query?.parentId) || 0))
// the first show loads too
onShow(() => void load())
</script>
